package com.tekwatt.billing.service;import com.tekwatt.billing.dto.*;import com.tekwatt.billing.entity.*;import com.tekwatt.billing.repository.BillRepository;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class BillingService{private final BillRepository repo;public BillingService(BillRepository r){repo=r;}public BillResponse create(CreateBillRequest r){if(repo.existsBySessionId(r.sessionId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Session is already billed");String number="TW-"+DateTimeFormatter.ofPattern("yyyyMMddHHmmss").withZone(ZoneOffset.UTC).format(Instant.now())+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase();return BillResponse.from(repo.save(new Bill(r.tenantId(),r.userId(),r.sessionId(),r.tariffId(),number,r.energyKwh(),r.durationMinutes(),r.energyPricePerKwh(),r.timePricePerMinute(),r.sessionFee(),r.taxPercent(),r.currency())));}@Transactional(readOnly=true)public BillResponse get(UUID id){return BillResponse.from(find(id));}@Transactional(readOnly=true)public List<BillResponse>list(UUID tenantId){return repo.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(BillResponse::from).toList();}public BillResponse pay(UUID id){Bill b=find(id);if(b.getStatus()!=BillStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending bills can be paid");b.pay();return BillResponse.from(b);}public BillResponse voidBill(UUID id){Bill b=find(id);if(b.getStatus()!=BillStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending bills can be voided");b.voidBill();return BillResponse.from(b);}private Bill find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Bill not found"));}}
